const row = items[0]?.json ?? {};

const leadId = row.lead_id;
const phoneNumber = row.phone_number || 'N/A';
const whatsappName = row.whatsapp_name || 'Sin nombre';
const service = row.service || 'No especificado';
const city = row.city || 'No especificada';
const requirement = row.requirement || 'No especificado';
const sellerName = row.seller_name || 'Sin asignar';
const createdAt = row.created_at ? new Date(row.created_at).toLocaleString('es-CL') : 'N/A';

const notificationText = [
  '🆕 *Nuevo Lead*',
  '',
  '👤 Nombre: ' + whatsappName,
  '📱 Teléfono: ' + phoneNumber,
  '🔧 Servicio: ' + service,
  '📍 Ciudad: ' + city,
  '📝 Requerimiento: ' + requirement,
  '👤 Vendedor asignado: ' + sellerName,
  '🕐 Fecha: ' + createdAt,
  '',
  'ID Lead: #' + leadId,
].join('\n');

const apiBaseUrl = String($env.EVOLUTION_API_BASE_URL || '').replace(/\/$/, '');
const apiKey = String($env.EVOLUTION_API_KEY || '').trim();
const instanceName = String($env.EVOLUTION_DEFAULT_INSTANCE || 'principal').trim();
const groupId = String($env.WHATSAPP_NOTIFICATION_GROUP_ID || '').trim();

if (!apiBaseUrl || !apiKey || !groupId) {
  throw new Error('WA - Group Notification: faltan variables de entorno (EVOLUTION_API_BASE_URL, EVOLUTION_API_KEY o WHATSAPP_NOTIFICATION_GROUP_ID)');
}

const outboundBody = {
  number: groupId,
  text: notificationText,
  delay: 0,
  linkPreview: false,
};

return [
  {
    json: {
      lead_id: leadId,
      notification_text: notificationText,
      group_id: groupId,
      outbound_url: apiBaseUrl + '/message/sendText/' + encodeURIComponent(instanceName),
      outbound_body: outboundBody,
    },
  },
];

const row = items[0]?.json ?? {};
const url = String(row.outbound_url || '').trim();
const body = row.outbound_body;

if (!url || !body) {
  return [{ json: { statusCode: 0, body: { message: 'Missing outbound_url or outbound_body' }, success: false } }];
}

try {
  const response = await helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      apikey: $env.EVOLUTION_API_KEY,
      'Content-Type': 'application/json',
    },
    body,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });

  const statusCode = Number(response.statusCode || 0);
  const success = statusCode >= 200 && statusCode < 300;

  return [{
    json: {
      lead_id: row.lead_id,
      group_id: row.group_id,
      statusCode,
      success,
      external_message_id: response.body?.key?.id || null,
    },
  }];
} catch (error) {
  return [{
    json: {
      lead_id: row.lead_id,
      group_id: row.group_id,
      statusCode: 0,
      success: false,
      error: error.message,
    },
  }];
}

const row = items[0]?.json ?? {};

const afterPayload = JSON.stringify({
  group_id: row.group_id || null,
  status_code: row.statusCode || 0,
  external_message_id: row.external_message_id || null,
});

const metadata = JSON.stringify({
  provider: 'evolution_api',
  channel: 'whatsapp_group',
  success: row.success || false,
  error: row.error || null,
});

return [{
  json: {
    lead_id: row.lead_id,
    success: String(row.success || false),
    after_payload_json: afterPayload,
    metadata_json: metadata,
  },
}];
